SET NAMES utf8mb4;
CREATE TABLE businesses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,rfc VARCHAR(13),status ENUM('active','suspended') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,plan VARCHAR(50) NOT NULL,status ENUM('trial','active','past_due','suspended','cancelled') NOT NULL DEFAULT 'trial',starts_at DATETIME NOT NULL,ends_at DATETIME NULL,FOREIGN KEY(business_id) REFERENCES businesses(id)) ENGINE=InnoDB;
CREATE TABLE branches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,code VARCHAR(30) NOT NULL,status ENUM('pending','active','suspended') NOT NULL DEFAULT 'pending',monthly_price DECIMAL(12,2) NOT NULL DEFAULT 0,activation_token_hash CHAR(64),activated_at DATETIME NULL,last_seen_at DATETIME NULL,UNIQUE(business_id,code),FOREIGN KEY(business_id) REFERENCES businesses(id)) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('owner','admin','manager','cashier','warehouse','employee') NOT NULL,status ENUM('active','disabled') DEFAULT 'active',UNIQUE(business_id,email),FOREIGN KEY(business_id) REFERENCES businesses(id),FOREIGN KEY(branch_id) REFERENCES branches(id)) ENGINE=InnoDB;
CREATE TABLE customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,phone VARCHAR(30),email VARCHAR(190),rfc VARCHAR(13),tax_name VARCHAR(255),tax_zip VARCHAR(10),tax_regime VARCHAR(10),cfdi_use VARCHAR(10),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,phone),FOREIGN KEY(business_id) REFERENCES businesses(id)) ENGINE=InnoDB;
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,sku VARCHAR(80),barcode VARCHAR(80),name VARCHAR(190) NOT NULL,unit ENUM('piece','kg','meter','liter','box','pack','roll') DEFAULT 'piece',cost DECIMAL(14,4) NOT NULL DEFAULT 0,price DECIMAL(14,4) NOT NULL DEFAULT 0,tax_rate DECIMAL(7,4) NOT NULL DEFAULT 0,sat_product_key VARCHAR(20),sat_unit_key VARCHAR(10),tax_object VARCHAR(10),active TINYINT(1) NOT NULL DEFAULT 1,UNIQUE(business_id,sku),INDEX(business_id,barcode),FOREIGN KEY(business_id) REFERENCES businesses(id)) ENGINE=InnoDB;
CREATE TABLE inventory (business_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,qty DECIMAL(16,4) NOT NULL DEFAULT 0,min_qty DECIMAL(16,4) NOT NULL DEFAULT 0,PRIMARY KEY(branch_id,product_id),FOREIGN KEY(business_id) REFERENCES businesses(id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE sales (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NULL,status ENUM('open','completed','cancelled','refunded') NOT NULL DEFAULT 'open',subtotal DECIMAL(14,2) NOT NULL DEFAULT 0,tax DECIMAL(14,2) NOT NULL DEFAULT 0,discount DECIMAL(14,2) NOT NULL DEFAULT 0,total DECIMAL(14,2) NOT NULL DEFAULT 0,cost_total DECIMAL(14,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,INDEX(business_id,branch_id,created_at),FOREIGN KEY(branch_id) REFERENCES branches(id)) ENGINE=InnoDB;
CREATE TABLE sale_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,description VARCHAR(190) NOT NULL,qty DECIMAL(16,4) NOT NULL,unit_price DECIMAL(14,4) NOT NULL,cost DECIMAL(14,4) NOT NULL,discount DECIMAL(14,2) NOT NULL DEFAULT 0,tax DECIMAL(14,2) NOT NULL DEFAULT 0,line_total DECIMAL(14,2) NOT NULL,FOREIGN KEY(sale_id) REFERENCES sales(id),FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT UNSIGNED NOT NULL,method ENUM('cash','card','transfer','credit','other') NOT NULL,amount DECIMAL(14,2) NOT NULL,reference VARCHAR(120),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(sale_id) REFERENCES sales(id)) ENGINE=InnoDB;
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NULL,channel ENUM('counter','whatsapp','phone','web','shopify','marketplace') DEFAULT 'counter',status ENUM('new','confirmed','preparing','ready','shipped','delivered','cancelled') DEFAULT 'new,total DECIMAL(14,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;